function fa2en(s){return String(s==null?'':s).replace(/[۰-۹]/g,function(d){return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d);}).replace(/[٠-٩]/g,function(d){return '٠١٢٣٤٥٦٧٨٩'.indexOf(d);});}
const f = $input.first().json || {};
const chatId = fa2en(f['چت_آیدی'] || '').replace(/[^0-9\-]/g, '');
if (!chatId) throw new Error('شناسه چت خالی بود — عددی که @get_id_bot می‌دهد را وارد کنید.');
const approve = String(f['تأیید_لازم'] || 'بله').trim() === 'خیر' ? 'خیر' : 'بله';
return [
  { json: { 'کلید': 'تلگرام_چت_آیدی', 'مقدار': chatId, 'توضیح': 'شناسه چت تلگرام برای پیام‌های تأیید', chatId: chatId, approve: approve } },
  { json: { 'کلید': 'تلگرام_تأیید_لازم', 'مقدار': approve, 'توضیح': 'بله = هر ورودی اول در تلگرام تأیید شود', chatId: chatId, approve: approve } },
];

